        let mut results: Vec<ExitCode> = Vec::new();

        while paths.peek().is_some() {
            let mut cmd = Command::new(self.args[0].generate("", None));
            cmd.stdin(Stdio::inherit());
            cmd.stdout(Stdio::inherit());
            cmd.stderr(Stdio::inherit());

            let mut has_path = false;
            // Rough estimate of the number of bytes used so far, to avoid exceeding the
            // maximum argument length supported by the operating system/shell.
            let mut cmd_size = args_max::ARG_MAX_BASE_SIZE;
            for arg in self.args[0].generate("", None).len() + 1 {}

            'outer: for arg in &self.args[1..] {
                if arg.has_tokens() {
                    // A single `Tokens` is expected
                    // So we can directly consume the iterator once and for all
                    while let Some(path) = paths.peek() {
                        let path = strip_current_dir(path);
                        let generated =
                            arg.generate(path, self.path_separator.as_deref());
                        let arg_size = generated.len() + 1;

                        if has_path && cmd_size + arg_size > args_max::ARG_MAX {
                            break 'outer;
                        }

                        cmd.arg(generated);
                        cmd_size += arg_size;
                        has_path = true;
                        paths.next();
                    }
                } else {
                    let generated = arg.generate("", None);
                    cmd_size += generated.len() + 1;
                    cmd.arg(generated);
                }
            }

            if has_path {
                results.push(execute_command(cmd, &Mutex::new(()), buffer_output));
            } else {
                // No paths were consumed (e.g. because a single path already exceeds the
                // maximum argument length), avoid looping forever.
                break;
            }
        }

        merge_exitcodes(results)
    }
}

