    pub fn generate_and_execute_batch<I>(&self, paths: I, buffer_output: bool) -> ExitCode
    where
        I: Iterator<Item = PathBuf>,
    {
        let mut paths: Vec<_> = paths.collect();
        paths.sort();
        let mut paths = paths.into_iter().peekable();

        // Maximum length (in bytes) of the argument list that we build up for a single
        // invocation of the command, so that we don't exceed the operating system's limit
        // (as returned by e.g. `getconf ARG_MAX`).
        let max_args_size = max_arg_list_length();

        let mut results: Vec<ExitCode> = Vec::new();

        while paths.peek().is_some() {
            let executable = self.args[0].generate("", None);
            let mut cmd = Command::new(&executable);
            cmd.stdin(Stdio::inherit());
            cmd.stdout(Stdio::inherit());
            cmd.stderr(Stdio::inherit());

            let mut has_path = false;
            // Rough estimate of the number of bytes used so far, to avoid exceeding the
            // maximum argument length supported by the operating system/shell.
            let mut cmd_size = executable.len() + 1;

            'outer: for arg in &self.args[1..] {
                if arg.has_tokens() {
                    // A single `Tokens` is expected, so we can directly consume the
                    // iterator here.
                    while let Some(path) = paths.peek() {
                        let path = strip_current_dir(path);
                        let generated = arg.generate(path, self.path_separator.as_deref());
                        let arg_size = generated.len() + 1;

                        if has_path && cmd_size + arg_size > max_args_size {
                            break 'outer;
                        }

                        cmd.arg(generated);
                        cmd_size += arg_size;
                        has_path = true;
                        paths.next();
                    }
                } else {
                    let generated = arg.generate("", None);
                    cmd_size += generated.len() + 1;
                    cmd.arg(generated);
                }
            }

            if has_path {
                results.push(execute_command(cmd, &Mutex::new(()), buffer_output));
            } else {
                // No paths were consumed (e.g. because a single path already exceeds the
                // maximum argument length), avoid looping forever.
                break;
            }
        }

        merge_exitcodes(results)
    }
}

/// Returns a conservative estimate (in bytes) of the maximum combined length of the
/// arguments that can be passed to a single invocation of a command, leaving some room
/// for the environment and other overhead.
fn max_arg_list_length() -> usize {
    #[cfg(all(unix, not(target_os = "redox")))]
    {
        let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
        if arg_max > 0 {
            // Leave some headroom for the environment variables that get passed along
            // with the command, and for other overhead that the shell/OS might add.
            return (arg_max as usize).saturating_sub(2048).max(4096);
        }
    }

    // A conservative, portable fallback value.
    128 * 1024
}
